import React, { useState, useEffect } from 'react';
import chatBgImg from '../../assets/nen_khung_chat.jpg';

const GuiYeuCauBaoTri = () => {
    const now = new Date();
    const [selectedDate, setSelectedDate] = useState(now.getDate());
    const [selectedMonth, setSelectedMonth] = useState(now.getMonth() + 1);
    const [selectedYear, setSelectedYear] = useState(now.getFullYear());

    const [userRoom, setUserRoom] = useState('');
    const [title, setTitle] = useState('');
    const [description, setDescription] = useState('');
    const [dailyRequests, setDailyRequests] = useState([]);
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        const profile = JSON.parse(localStorage.getItem('userProfile') || '{}');
        setUserRoom(profile.room_id || profile.room || '102');
        fetchData();
    }, [selectedDate, selectedMonth, selectedYear]);

    // Logic fetch data sẵn sàng cho Backend
    const fetchData = () => {
        setLoading(true);
        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        const filtered = allData.filter(item => 
            item.day === selectedDate && item.month === selectedMonth && item.year === selectedYear
        );
        setTimeout(() => {
            setDailyRequests(filtered);
            setLoading(false);
        }, 300);
    };

    const handleSendRequest = () => {
        if (!title.trim() || !description.trim()) {
            alert("Vui lòng nhập đầy đủ tiêu đề và mô tả!");
            return;
        }

        const newRequest = {
            id: Date.now(),
            room: userRoom,
            title: title,
            issue: description,
            status: 'pending',
            day: selectedDate,
            month: selectedMonth,
            year: selectedYear,
            time: new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
        };

        const allData = JSON.parse(localStorage.getItem('maintenance_db') || '[]');
        localStorage.setItem('maintenance_db', JSON.stringify([newRequest, ...allData]));

        setTitle('');
        setDescription('');
        fetchData();
        alert("Gửi yêu cầu thành công!");
    };

    return (
        <div style={containerStyle} className="glass-card">
            {/* Header đồng bộ XemHoaDon */}
            <div style={headerStyle}>
                <h2 style={{ color: '#fff', margin: 0, fontSize: '20px' }}>🛠 YÊU CẦU BẢO TRÌ</h2>
                <div style={{ display: 'flex', gap: '10px' }}>
                    <select value={selectedDate} onChange={(e) => setSelectedDate(Number(e.target.value))} style={selectStyle}>
                        {Array.from({length:31},(_,i)=><option key={i+1} value={i+1}>Ngày {i+1}</option>)}
                    </select>
                    <select value={selectedMonth} onChange={(e) => setSelectedMonth(Number(e.target.value))} style={selectStyle}>
                        {[...Array(12)].map((_, i) => <option key={i+1} value={i+1}>Tháng {i+1}</option>)}
                    </select>
                </div>
            </div>

            <div style={contentWrapperStyle}>
                <div style={mainLayout}>

                    {/* CỘT TRÁI: FORM NHẬP (TRẮNG ĐẶC - RÕ) */}
                    <div style={whiteCardForm}>
                        <div style={roomDisplay}>
                            <span style={{ fontSize: '13px', color: '#8b5e5e', fontWeight: 'bold' }}>MÃ SỐ PHÒNG</span>
                            <div style={{ fontSize: '32px', fontWeight: '900', color: '#333' }}>{userRoom}</div>
                        </div>

                        <div style={inputGroup}>
                            <label style={labelStyle}>Tiêu đề sự cố:</label>
                            <input 
                                style={inputStyle} 
                                value={title} 
                                onChange={(e) => setTitle(e.target.value)} 
                                placeholder="VD: Hỏng bóng đèn, tắc bồn rửa..." 
                            />
                        </div>

                        <div style={inputGroup}>
                            <label style={labelStyle}>Mô tả chi tiết:</label>
                            <textarea 
                                style={textareaStyle} 
                                value={description} 
                                onChange={(e) => setDescription(e.target.value)} 
                                placeholder="Mô tả cụ thể tình trạng hoặc vị trí sự cố..." 
                            />
                        </div>

                        <button onClick={handleSendRequest} style={btnSubmitStyle}>XÁC NHẬN GỬI</button>
                    </div>

                    {/* CỘT PHẢI: DANH SÁCH (TRẮNG ĐẶC - RÕ) */}
                    <div style={whiteCardList}>
                        <h3 style={{ color: '#8b5e5e', fontSize: '16px', textAlign: 'center', marginBottom: '20px' }}>LỊCH SỬ GỬI HÔM NAY</h3>

                        {loading ? (
                            <div style={statusMsg}>Đang kiểm tra...</div>
                        ) : (
                            <div style={{ overflowY: 'auto', flex: 1, paddingRight: '5px' }} className="custom-scrollbar">
                                {dailyRequests.length > 0 ? dailyRequests.map(req => (
                                    <div key={req.id} style={itemBox}>
                                        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                                            <strong style={{fontSize: '14px', color: '#333'}}>{req.title}</strong>
                                            <span style={badgeStyle(req.status)}>{req.status === 'pending' ? 'Chờ' : 'Xong'}</span>
                                        </div>
                                        <p style={{ fontSize: '12px', color: '#666', margin: '8px 0' }}>{req.issue}</p>
                                        <div style={{ fontSize: '10px', color: '#bbb', textAlign: 'right' }}>{req.time}</div>
                                    </div>
                                )) : (
                                    <div style={statusMsg}>Trống</div>
                                )}
                            </div>
                        )}
                    </div>

                </div>
            </div>
            <style>{`
                @keyframes fadeIn { from { opacity: 0; transform: translateY(10px); } to { opacity: 1; transform: translateY(0); } }
                .custom-scrollbar::-webkit-scrollbar { width: 4px; }
                .custom-scrollbar::-webkit-scrollbar-thumb { background: #eee; border-radius: 10px; }
            `}</style>
        </div>
    );
};

// --- STYLES ĐỒNG BỘ 100% XEMHOADON ---
const containerStyle = { flex: 1, borderRadius: '30px', display: 'flex', flexDirection: 'column', backgroundImage: `url(${chatBgImg})`, backgroundSize: 'cover', backgroundPosition: 'center', height: 'calc(100vh - 120px)', overflow: 'hidden' };
const headerStyle = { padding: '20px 30px', display: 'flex', justifyContent: 'space-between', alignItems: 'center', background: 'rgba(0,0,0,0.3)' };
const selectStyle = { padding: '8px 12px', borderRadius: '10px', border: 'none', fontWeight: 'bold', cursor: 'pointer' };
const contentWrapperStyle = { flex: 1, display: 'flex', padding: '25px', overflow: 'hidden' };
const mainLayout = { display: 'flex', gap: '25px', width: '100%', animation: 'fadeIn 0.4s' };

// Khối Form bên trái (Giống mainFormStyle của XemHoaDon)
const whiteCardForm = { 
    width: '380px', 
    backgroundColor: '#fff', 
    borderRadius: '30px', 
    padding: '35px', 
    boxShadow: '0 15px 35px rgba(0,0,0,0.2)', 
    display: 'flex', 
    flexDirection: 'column' 
};

// Khối Danh sách bên phải (Cùng phong cách trắng đặc)
const whiteCardList = { 
    flex: 1, 
    backgroundColor: '#fff', 
    borderRadius: '30px', 
    padding: '35px', 
    boxShadow: '0 15px 35px rgba(0,0,0,0.15)', 
    display: 'flex', 
    flexDirection: 'column' 
};

const roomDisplay = { textAlign: 'center', padding: '15px', background: '#fdf3f3', borderRadius: '20px', marginBottom: '25px', border: '2px dashed #8b5e5e' };
const inputGroup = { marginBottom: '20px' };
const labelStyle = { display: 'block', fontWeight: 'bold', marginBottom: '8px', color: '#666', fontSize: '13px' };
const inputStyle = { width: '100%', padding: '12px 15px', borderRadius: '12px', border: '1px solid #ddd', fontSize: '15px', outline: 'none', boxSizing: 'border-box' };
const textareaStyle = { ...inputStyle, height: '100px', resize: 'none' };
const btnSubmitStyle = { width: '100%', padding: '16px', borderRadius: '15px', border: 'none', backgroundColor: '#8b5e5e', color: '#fff', fontWeight: 'bold', fontSize: '16px', cursor: 'pointer', marginTop: '10px' };

